L5_1.m_fTalkTime = 0.03
L6_1 = "\229\191\181\229\139\149\229\138\155\227\129\167\230\139\152\230\157\159\227\129\151\227\129\159\227\128\130\231\132\161\231\144\134\227\130\132\227\130\138\230\138\156\227\129\145\227\130\136\227\129\134\227\129\168\227\129\153\227\130\140\227\129\176\230\128\170\230\136\145\227\129\153\227\130\139\227\129\139\227\130\137\229\139\149\227\129\139\227\129\170\227\129\132\230\150\185\227\129\140\227\129\132\227\129\132\227\128\130"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I restrained you with telekinesis. You'll get hurt if you try to free yourself by force, so I suggest you stay still."
