L5_1.m_Talk_TWN = L6_1
L6_1 = "\228\189\160\229\183\178\231\187\143\232\162\171\230\136\145\231\148\168\229\191\181\229\138\155\230\157\159\231\188\154\228\189\143\228\186\134\227\128\130\229\188\186\232\161\140\230\140\163\232\132\177\231\154\132\232\175\157\239\188\140\229\143\175\230\152\175\228\188\154\229\143\151\228\188\164\231\154\132\239\188\140\232\191\152\230\152\175\232\128\129\229\174\158\229\190\133\231\157\128\229\144\167\227\128\130"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich habe dich durch Psychokinese zur\195\188ckgehalten. Wenn du versuchst, dich mit Gewalt zu befreien, wirst du verletzt. Ich rate dir also, ruhig zu bleiben."
