L9_1 = "\234\183\184\235\130\152\236\160\128\235\130\152 \236\185\168\236\139\157\237\140\140\235\165\188 \234\176\144\236\167\128\237\149\156 \234\177\180\234\176\128\226\128\166\226\128\166. \236\157\180\236\136\152\236\151\176\236\157\180 \236\163\188\236\157\152\237\149\152\235\157\188\235\141\152 \236\157\180\236\156\160\234\176\128 \236\158\136\236\151\136\234\181\176."
