L8_1.m_fTalkTime = 0.03
L9_1 = "\227\129\157\227\130\140\227\129\171\227\129\151\227\129\166\227\130\130\228\190\181\233\163\159\230\179\162\227\130\146\230\132\159\231\159\165\227\129\151\227\129\159\227\129\168\227\129\132\227\129\134\227\129\174\227\129\139\226\128\166\226\128\166\227\130\171\227\131\138\227\131\159\227\129\140\230\176\151\227\130\146\228\187\152\227\129\145\227\130\141\227\129\168\232\168\128\227\129\134\227\129\160\227\129\145\227\129\175\227\129\130\227\130\139\227\128\130"
L8_1.m_Talk_JPN = L9_1
L9_1 = "But to detect Corruption rays... I understand why Lee Sooyeon told me to be careful."
L8_1.m_Talk_ENG = L9_1
L9_1 = "\228\184\141\233\129\142\230\152\175\230\156\137\230\132\159\230\135\137\229\136\176\228\190\181\232\157\149\230\179\162\229\151\142\226\128\166\226\128\166 \230\137\128\228\187\165\230\157\142\231\167\128\229\166\141\230\137\141\230\156\131\232\166\129\230\136\145\230\179\168\230\132\143\229\151\142\239\188\159"
L8_1.m_Talk_TWN = L9_1
L9_1 = "\233\154\190\233\129\147\230\152\175\230\132\159\232\167\137\229\136\176\228\186\134\230\136\145\231\154\132\228\190\181\232\154\128\230\179\162\226\128\166\226\128\166\239\188\159\231\167\128\229\166\141\232\174\169\230\136\145\229\176\143\229\191\131\239\188\140\230\158\156\231\132\182\230\152\175\230\156\137\229\142\159\229\155\160\231\154\132\227\128\130"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Aber die Tatsache, dass sie die Verderbniswellen erkannt hat ... Ich verstehe jetzt, warum Lee Sooyeon zu mir meinte, ich solle vorsichtig sein."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Mais parvenir \195\160 d\195\169tecter les rayons de Corruption... Je comprends pourquoi Lee Sooyeon m'a dit de faire attention."
