L11_1.m_Talk_SCN = L12_1
L12_1 = "Jeder hier kennt den Ausdruck, den du damals im Gesicht hattest, immer wenn die Kinder geweint haben. Auch wenn du stets gesagt hast, dass es dir egal w\195\164re."
