L14_1 = "\227\129\191\227\130\147\227\129\170\227\130\130\231\167\129\227\130\130\227\128\129\227\129\130\227\129\170\227\129\159\227\129\171\227\129\175\232\139\166\227\129\151\227\130\147\227\129\167\227\129\187\227\129\151\227\129\143\227\129\170\227\129\132\227\129\168\230\128\157\227\129\163\227\129\166\227\129\132\227\130\139\227\129\174\227\128\130\228\187\138\227\129\167\227\130\130\229\141\129\229\136\134\232\190\155\227\129\132\227\129\167\227\129\151\227\130\135\227\129\134\227\129\139\227\130\137\227\128\130"
