L13_1.m_Talk_TWN = L14_1
L14_1 = "\230\136\145\229\146\140\229\173\169\229\173\144\228\187\172\233\131\189\229\184\140\230\156\155\228\189\160\228\184\141\232\166\129\233\154\190\232\191\135\227\128\130\230\175\149\231\171\159\228\189\160\231\142\176\229\156\168\229\183\178\231\187\143\229\164\159\231\180\175\228\186\134\227\128\130"
