L49_1 = "\232\169\166\228\189\156\229\147\129\227\130\146\232\166\139\227\129\159\230\153\130\227\129\171\227\131\148\227\131\179\227\129\168\227\129\141\227\129\159\227\129\174\227\128\130\227\129\130\227\129\174\228\186\186\227\129\140\227\129\190\227\129\168\227\130\130\227\129\170\227\130\130\227\129\174\227\130\146\232\166\139\227\129\155\227\129\166\227\129\143\227\130\139\227\130\143\227\129\145\227\129\140\227\129\170\227\129\132\227\130\130\227\129\174\227\128\130"
