L48_1.m_Talk_TWN = L49_1
L49_1 = "\230\136\145\228\184\128\231\156\139\229\136\176\232\175\149\229\136\182\229\147\129\229\176\177\230\156\137\231\167\141\231\155\180\232\167\137\227\128\130\229\155\160\228\184\186\233\130\163\228\184\170\228\186\186\228\184\141\229\143\175\232\131\189\230\139\191\229\135\186\228\187\128\228\185\136\229\165\189\228\184\156\232\165\191\227\128\130"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich wusste es sofort, als ich den Prototyp gesehen habe. Der Boss ist nicht der Typ, dem so ein beachtliches Modell einf\195\164llt."
