L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "\231\164\190\229\134\133\227\129\171\227\129\130\227\130\147\227\129\170\227\130\130\227\129\174\227\130\146\228\189\156\227\130\140\227\130\139\230\137\141\232\131\189\227\129\140\227\129\130\227\130\139\228\186\186\227\129\175\227\129\132\227\129\170\227\129\132\227\129\145\227\130\140\227\129\169\227\128\129\227\129\130\227\129\170\227\129\159\227\129\170\227\130\137\229\135\186\230\157\165\227\130\139\227\129\168\230\128\157\227\129\163\227\129\166\227\128\130"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I don't think there is anyone in the company with that kind of talent, but it would be possible with your dexterity."
