L49_1.m_Talk_TWN = L50_1
L50_1 = "\229\133\172\229\143\184\233\135\140\232\153\189\231\132\182\230\178\161\230\156\137\233\130\163\231\167\141\228\186\186\230\137\141\239\188\140\228\189\134\229\135\173\228\189\160\230\137\139\232\137\186\232\191\152\230\152\175\232\131\189\229\129\154\229\136\176\231\154\132\227\128\130"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich glaube nicht, dass es im Unternehmen jemanden mit so einem Talent gibt, aber mit deiner Geschicklichkeit w\195\164re es m\195\182glich, so etwas herzustellen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je ne pensais pas qu'il y avait quelqu'un dans l'entreprise poss\195\169dant ce genre de talent, mais avec ta dext\195\169rit\195\169, c'est vrai que c'est possible."
