L50_1.m_fTalkTime = 0.03
L51_1 = "\226\128\166\226\128\166\233\157\162\231\155\174\227\129\170\227\129\132\227\128\130\227\129\151\227\129\139\227\129\151\227\130\171\227\131\138\227\131\159\227\128\130\229\144\155\227\130\146\233\168\153\227\129\153\227\129\164\227\130\130\227\130\138\227\129\167\227\129\175\227\129\170\227\129\139\227\129\163\227\129\159\227\128\130"
