L4_1 = "\230\153\174\230\174\181\227\129\170\227\129\139\227\129\170\227\129\139\228\188\154\227\129\136\227\129\170\227\129\132\227\130\147\227\129\160\227\129\151\227\128\129\227\129\147\227\129\134\227\130\132\227\129\163\227\129\166\227\131\129\227\131\163\227\131\179\227\130\185\227\129\140\227\129\130\227\130\139\227\129\168\227\129\141\227\129\171\228\184\128\231\183\146\227\129\171\233\129\142\227\129\148\227\129\151\227\129\159\227\129\132\227\130\143\227\128\130"
