L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "\227\129\132\227\129\164\227\130\130\230\128\157\227\129\134\227\129\140\227\128\129\227\130\130\227\129\134\227\129\153\227\129\163\227\129\139\227\130\138\229\164\167\228\186\186\227\129\160\227\129\170\227\128\130\229\143\163\227\129\174\228\184\138\230\137\139\227\129\149\227\129\167\227\129\175\227\130\130\227\129\134\230\149\181\227\130\143\227\129\170\227\129\132\227\128\130"
