L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich hatte schon immer das Gef\195\188hl, aber du bist wirklich erwachsen geworden. Du bist so wortgewandt, dass ich dir nichts entgegenzusetzen habe."
